#!/usr/bin/env python3
"""Dialogue script parser that converts text scripts into structured JSON graphs and DOT visualizations."""

import re
import json
from collections import deque


def parse_script(text: str) -> dict:
    """Parse a dialogue script into a structured graph with nodes and edges.

    Args:
        text: The raw script text content.

    Returns:
        A dictionary with "nodes" and "edges" lists.
    """
    nodes = []
    edges = []
    node_ids_seen = set()
    current_node_id = None

    for line in text.split('\n'):
        line = line.strip()
        if not line:
            continue

        # Match node header: [NodeId]
        header_match = re.match(r'^\[(\w+)\]$', line)
        if header_match:
            current_node_id = header_match.group(1)
            continue

        if current_node_id is None:
            continue

        # Match choice line: N. text -> Target
        choice_match = re.match(r'^(\d+)\.\s+(.+?)\s*->\s*(\w+)$', line)
        if choice_match:
            choice_text = choice_match.group(2).strip()
            target = choice_match.group(3).strip()

            # Add the choice node only once
            if current_node_id not in node_ids_seen:
                node_ids_seen.add(current_node_id)
                nodes.append({
                    "id": current_node_id,
                    "text": "",
                    "speaker": "",
                    "type": "choice"
                })

            edges.append({
                "from": current_node_id,
                "to": target,
                "text": choice_text
            })
            continue

        # Match dialogue line: Speaker: text -> Target
        # Speaker is everything before the first ": " (colon-space),
        # but we need to be careful with text that also contains colons.
        line_match = re.match(r'^([A-Za-z][\w\s]*?):\s(.+?)\s*->\s*(\w+)$', line)
        if line_match:
            speaker = line_match.group(1).strip()
            dialogue_text = line_match.group(2).strip()
            target = line_match.group(3).strip()

            if current_node_id not in node_ids_seen:
                node_ids_seen.add(current_node_id)
                nodes.append({
                    "id": current_node_id,
                    "text": dialogue_text,
                    "speaker": speaker,
                    "type": "line"
                })

            edges.append({
                "from": current_node_id,
                "to": target,
                "text": ""
            })
            continue

    # Add the "End" node if it's referenced by any edge but not defined
    edge_targets = {e["to"] for e in edges}
    for target in edge_targets:
        if target not in node_ids_seen:
            node_ids_seen.add(target)
            nodes.append({
                "id": target,
                "text": target,
                "speaker": "",
                "type": "line"
            })

    return {"nodes": nodes, "edges": edges}


def validate_graph(graph: dict) -> bool:
    """Validate that the graph meets all constraints.

    1. All nodes reachable from the first node.
    2. All edge targets exist as nodes.
    3. Multiple paths can lead to End.
    """
    if not graph["nodes"]:
        return True

    node_ids = {n["id"] for n in graph["nodes"]}

    # Check all edge targets exist
    for edge in graph["edges"]:
        if edge["to"] not in node_ids:
            raise ValueError(f"Edge target '{edge['to']}' does not exist as a node")
        if edge["from"] not in node_ids:
            raise ValueError(f"Edge source '{edge['from']}' does not exist as a node")

    # Check reachability from first node via BFS
    start = graph["nodes"][0]["id"]
    adj = {}
    for edge in graph["edges"]:
        adj.setdefault(edge["from"], []).append(edge["to"])

    visited = set()
    queue = deque([start])
    while queue:
        node = queue.popleft()
        if node in visited:
            continue
        visited.add(node)
        for neighbor in adj.get(node, []):
            if neighbor not in visited:
                queue.append(neighbor)

    unreachable = node_ids - visited
    if unreachable:
        raise ValueError(f"Unreachable nodes from '{start}': {unreachable}")

    # Check that End node exists and is reachable
    if "End" in node_ids and "End" not in visited:
        raise ValueError("End node is not reachable from the start")

    return True


def generate_dot(graph: dict) -> str:
    """Generate a Graphviz DOT representation of the dialogue graph."""
    lines = ['digraph dialogue {']
    lines.append('    rankdir=TB;')
    lines.append('    node [style=filled, fontname="Arial"];')
    lines.append('')

    for node in graph["nodes"]:
        # Escape special characters for DOT labels
        label = node["text"].replace('\\', '\\\\').replace('"', '\\"')
        if node["speaker"]:
            speaker = node["speaker"].replace('"', '\\"')
            label = f'{speaker}: {label}'

        # Truncate long labels for readability
        if len(label) > 80:
            label = label[:77] + "..."

        node_id = node["id"]

        if node_id == "End":
            lines.append(f'    {node_id} [label="{label}" shape=doublecircle fillcolor=lightcoral];')
        elif node["type"] == "choice":
            lines.append(f'    {node_id} [label="{node_id}" shape=diamond fillcolor=lightskyblue];')
        else:
            lines.append(f'    {node_id} [label="{label}" shape=box fillcolor=lightyellow];')

    lines.append('')

    for edge in graph["edges"]:
        edge_label = edge["text"].replace('\\', '\\\\').replace('"', '\\"')
        # Truncate long edge labels
        if len(edge_label) > 50:
            edge_label = edge_label[:47] + "..."

        if edge_label:
            lines.append(f'    {edge["from"]} -> {edge["to"]} [label="{edge_label}"];')
        else:
            lines.append(f'    {edge["from"]} -> {edge["to"]};')

    lines.append('}')
    return '\n'.join(lines)


def main():
    # Read the script
    with open("/app/script.txt", "r") as f:
        text = f.read()

    # Parse
    graph = parse_script(text)

    # Validate
    validate_graph(graph)

    # Write JSON
    with open("/app/dialogue.json", "w") as f:
        json.dump(graph, f, indent=2)

    # Write DOT
    dot = generate_dot(graph)
    with open("/app/dialogue.dot", "w") as f:
        f.write(dot)

    print(f"Parsed {len(graph['nodes'])} nodes and {len(graph['edges'])} edges")
    print("Output written to /app/dialogue.json and /app/dialogue.dot")

    # Print validation summary
    node_types = {}
    for n in graph["nodes"]:
        node_types[n["type"]] = node_types.get(n["type"], 0) + 1
    print(f"Node types: {node_types}")

    # Count paths to End
    end_edges = [e for e in graph["edges"] if e["to"] == "End"]
    print(f"Paths to End: {len(end_edges)}")


if __name__ == "__main__":
    main()

